INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass schneller Support immer zufriedene Kunden garantiert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität zählt ebenso"}, {"text": "Ja", "correct": false, "because": "Nicht allein entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich die Zufriedenheit meiner IT-Kunden steigern will?', 3, '[{"text": "Kundenfeedback", "correct": true, "because": "Zeigt Verbesserungspotenzial"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Nur ein Aspekt"}, {"text": "Bunte Werbung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen erhöhen die Zufriedenheit von IT-Kunden?', 5, '[{"text": "Zuverlässiger Support", "correct": true, "because": "Löst Probleme"}, {"text": "Klare Kommunikation", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Höhere Preise", "correct": false, "because": "Kann abschrecken"}, {"text": "Komplexe Prozesse", "correct": false, "because": "Frustriert Kunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kundenzufriedenheit steigert Loyalität. b) Sie hängt nur von Preisen ab.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mehr als Preis relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich die Zufriedenheit bei IT-Dienstleistungen verbessere?', 4, '[{"text": "Kundenerwartungen", "correct": false, "because": "Grundlage für Zufriedenheit"}, {"text": "Servicequalität", "correct": false, "because": "Entscheidend für Erfolg"}, {"text": "Bürodeko", "correct": true, "because": "Kein Kundeneinfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob regelmäßige Updates immer Kunden zufriedenstellen?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität über Häufigkeit"}, {"text": "Ja", "correct": false, "because": "Nicht allein entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich die Zufriedenheit bei IT-Kunden erhöhe?', 3, '[{"text": "Kundenbindung", "correct": true, "because": "Sichert Wiederholungsgeschäft"}, {"text": "Schnellere Projekte", "correct": false, "because": "Nicht primär"}, {"text": "Weniger Support", "correct": false, "because": "Kein direktes Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Zufriedenheit von IT-Kunden?', 5, '[{"text": "Reaktionszeit", "correct": true, "because": "Zeigt Servicequalität"}, {"text": "Produktzuverlässigkeit", "correct": true, "because": "Erfüllt Erwartungen"}, {"text": "Hohe Kosten", "correct": false, "because": "Kann unzufrieden machen"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Guter Support steigert Zufriedenheit. b) Kunden wollen immer kostenlose Dienste. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten nicht allein entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um die Zufriedenheit bei IT-Kunden zu fördern?', 4, '[{"text": "Kundenkommunikation", "correct": false, "because": "Sichert Verständnis"}, {"text": "Feedbackanalyse", "correct": false, "because": "Zeigt Schwächen"}, {"text": "Luxusverpackung", "correct": true, "because": "Kein Servicefaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind zufriedene Kunden immer loyal?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Faktoren wirken"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt hohe Kundenzufriedenheit in der IT?', 4, '[{"text": "Positive Empfehlungen", "correct": true, "because": "Fördert Neukunden"}, {"text": "Wiederholungsgeschäft", "correct": true, "because": "Sichert Umsatz"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Kundenzufriedenheit nur von Technik abhängt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Service ebenso wichtig"}, {"text": "Ja", "correct": false, "because": "Zu einseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um die Zufriedenheit bei IT-Kunden zu messen?', 3, '[{"text": "Umfragen", "correct": true, "because": "Liefert direktes Feedback"}, {"text": "Schnellere Server", "correct": false, "because": "Kein Messinstrument"}, {"text": "Bunte Designs", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Zufriedenheit hängt von Erwartungen ab. b) Sie ist immer messbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Messbarkeit nicht absolut"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte fördern die Zufriedenheit bei IT-Kunden?', 5, '[{"text": "Schnelle Problemlösung", "correct": true, "because": "Erfüllt Bedarf"}, {"text": "Transparenz", "correct": true, "because": "Schafft Vertrauen"}, {"text": "Hohe Preise", "correct": false, "because": "Kann abschrecken"}, {"text": "Komplexe Anleitungen", "correct": false, "because": "Frustriert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich die Zufriedenheit bei IT-Kunden steigere?', 3, '[{"text": "Supportqualität", "correct": false, "because": "Kernfaktor"}, {"text": "Kundenwünsche", "correct": false, "because": "Leiten Maßnahmen"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Servicefaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Kundenzufriedenheit nur von Produkten abhängig?', 3, '[{"text": "Nein", "correct": true, "because": "Service ebenso entscheidend"}, {"text": "Ja", "correct": false, "because": "Zu einseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob regelmäßiger Kontakt immer zufriedene Kunden schafft?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität des Kontakts zählt"}, {"text": "Ja", "correct": false, "because": "Nicht allein ausschlaggebend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, um die Zufriedenheit bei IT-Kunden zu sichern?', 4, '[{"text": "Kundenzentrierung", "correct": true, "because": "Fokussiert auf Bedarf"}, {"text": "Schnelle Updates", "correct": false, "because": "Nur ein Aspekt"}, {"text": "Luxusdesign", "correct": false, "because": "Irrelevant"}]');
